// Two Sum - Find indices of two numbers that add up to target
var array = AnimatedArray<Int>()
array.append(2)
array.append(7)
array.append(11)
array.append(15)
let target = 9

func findTwoSum(arr: inout AnimatedArray<Int>, target: Int) -> [Int] {
    for i in 0..<arr.count {
        for j in (i + 1)..<arr.count {
            if let val1 = arr.at(i), let val2 = arr.at(j), val1 + val2 == target {
                return [i, j]
            }
        }
    }
    return []
}

let result = findTwoSum(arr: &array, target: target)
